import os
import re

def split_filename_version(name):
    stem, suffix = os.path.splitext(str(name))
    match = re.fullmatch(r"(.*)-v(\d+)", stem)
    if not match:
        return (stem, None, suffix)
    return (match.group(1), int(match.group(2)), suffix)
